function industriesPage(){const data=window.industryModules;if(!data?.sectors)return `${header('Industry sources','Source library is unavailable.','Reload the page to load the sector source cards.')}`;return `${header('Industry source library','Signals by industry.','Free public sources with their update cadence, access limits, and operating-metric hypothesis attached.',`<strong>${data.sectors.reduce((n,x)=>n+x.cards.length,0)}</strong> reviewed cards`)}<nav class="sector-index" aria-label="Sector index">${data.sectors.map(sector=>`<a href="#industries" data-sector-target="${esc(sector.id)}">${esc(sector.name)}</a>`).join('')}</nav><label class="field sector-search"><span>Filter by sector, source, or metric</span><input id="sector-search" type="search" placeholder="Try grid, revenue, wages, or streaming"></label>${data.sectors.map(sector=>`<section class="section industry-section" id="${esc(sector.id)}"><div class="section-title"><div><h2>${esc(sector.name)}</h2><p>${esc(sector.description)}</p></div></div><div class="industry-cards">${sector.cards.map(c=>`<article class="card card-pad industry-card"><div class="industry-card-head"><div><span class="tag">${esc(c.provider)}</span><h3>${esc(c.title)}</h3></div><div class="card-actions"><a class="btn" href="${esc(c.url)}" target="_blank" rel="noreferrer">Open source ↗</a>${trackButton({title:c.title,url:c.url,measure:c.operatingMetricBridge.metric,sector:sector.name})}</div></div><p>${esc(c.whatItMeasures)}</p><div class="receipt"><div><small>Freshness</small><strong>${esc(c.freshness)}</strong></div><div><small>Free access and reuse</small><strong>${esc(c.accessAndReuse)}</strong></div></div><div class="saved-bridge"><strong>Operating-metric hypothesis</strong><p>${esc(c.operatingMetricBridge.hypothesis)}</p><small>Measure: ${esc(c.operatingMetricBridge.metric)} Limits: ${esc(c.operatingMetricBridge.limits)}</small></div><p class="footnote">${esc(c.evidenceReviewed)}</p></article>`).join('')}</div></section>`).join('')}<p class="footnote">Source pages were checked 12 October 2026. Provider update claims and displayed timestamps are shown separately. Recheck terms and the latest observation before use.</p>`}
