function otherMarketsPage(){return `${header('Other markets','Company filings outside Taiwan','Use these official systems for filings and operating disclosures. Coverage, accounting periods, and access differ by market.',`<strong>${otherMarketSystems.length}</strong> systems`)}<section class="card card-pad"><div class="card-head"><div><h2>Monthly company revenue</h2><p class="sub">Taiwan is the only broad cross-industry monthly revenue filing system identified in this review.</p></div><span class="tag">Taiwan tab ↗</span></div><p>Domestic primary-listed issuers generally report the prior month’s operating revenue by the 10th. Special-scope rules create exceptions, and the filing is revenue, not a full monthly income statement. Other markets below mainly provide quarterly, annual, or event-driven company disclosures.</p><div class="card-actions"><a class="btn" href="https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0400001" target="_blank" rel="noreferrer">Taiwan law, Article 36 ↗</a><a class="btn" href="https://data.gov.tw/dataset/18420" target="_blank" rel="noreferrer">Official monthly revenue dataset ↗</a><a class="btn" href="https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0400152" target="_blank" rel="noreferrer">Scope exceptions ↗</a><a class="btn" href="#taiwan">Open Taiwan data ↗</a></div><p class="footnote">Hong Kong’s monthly return is a useful false-positive check: it records securities-capital movements, not revenue. Some Japanese issuers publish monthly sales voluntarily, but there is no all-issuer monthly series in this list.</p></section><div class="industry-cards section">${otherMarketSystems.map(s=>`<article class="card card-pad"><div class="industry-card-head"><div><span class="tag">${esc(s.market)}</span><h2 style="margin:8px 0 0;font-size:16px">${esc(s.name)}</h2></div><a class="btn" href="${esc(s.url)}" target="_blank" rel="noreferrer">Open source ↗</a></div><p>${esc(s.measure)}</p><div class="receipt"><div><small>Cadence</small><strong>${esc(s.cadence)}</strong></div><div><small>Access</small><strong>${esc(s.access)}</strong></div></div><p class="footnote">${esc(s.limit)}</p></article>`).join('')}</div><section class="card card-pad section"><div class="card-head"><div><h2>Expert calls and investor pitches</h2><p class="sub">Read expert-call research in your account. Keep future pitch summaries linked to the original public post and its date.</p></div><span class="tag amber">Login required</span></div><p>AlphaSense Expert Insights includes expert-call content for entitled accounts. This Field Signals page links to AlphaSense but does not copy transcripts. A future daily pitch digest should use public posts, permitted feeds, or content you are authorized to access.</p><a class="btn" href="https://www.alpha-sense.com/" target="_blank" rel="noreferrer">Open AlphaSense ↗</a></section>`}
let taiwanFeedRows=[];let taiwanPageNumber=0;
function taiwanPage(){const url=window.FIELD_SIGNAL_TAIWAN_FEED_URL||'';const count=taiwanFeedRows.length?'<strong>'+taiwanFeedRows.length.toLocaleString()+' issuers</strong>':'<strong>Feed not connected</strong>';return header('Taiwan company data','Monthly revenue and filed financials','Official reporting for listed, OTC, emerging, and publicly issued companies. Private companies are outside these filings.',count)+'<section class="card card-pad"><div class="card-head"><div><h2>Company revenue signals</h2><p class="sub">Monthly MOPS revenue in TWD thousands. Reports arrive after month-end, so this is not real-time data.</p></div><div class="card-actions"><a class="btn" href="https://data.gov.tw/dataset/91998" target="_blank" rel="noreferrer">MOPS filing dataset ↗</a><a class="btn" href="#other-markets">Other markets ↗</a></div></div><div class="receipt"><div><small>Revenue</small><strong>Reported monthly revenue with MoM, YoY, and year-to-date comparisons</strong></div><div><small>Feed contents</small><strong>One latest row per issuer, with change metrics calculated from earlier monthly reports</strong></div><div><small>Trend</small><strong>Δ1, Δ2, and Δ3 track changes in YoY growth when enough consecutive reports exist</strong></div><div><small>Read-through</small><strong>Compare growth with the company’s own mix, volume, pricing, and filed statements</strong></div></div><div class="field sector-search" style="margin-top:14px"><label for="taiwan-search">Find a company</label><input id="taiwan-search" type="search" placeholder="Ticker, Chinese or English name, industry"></div><p id="taiwan-feed-status" class="callout" style="margin-top:12px">'+(url?'Loading the published Google Sheets feed…':'The public data feed has not been connected.')+'</p><div class="raw-preview" id="taiwan-feed-table"></div><p class="footnote">This page shows a latest-row snapshot, not the monthly observation history. English names come from exchange profiles where available. Every row has a Mandarin pronunciation lookup. Large growth rates can reflect a small comparison base. Generic margins stay blank where filings cannot be matched safely.</p></section><section class="industry-cards section"><article class="card card-pad"><h3>In the workbook</h3><p>Monthly revenue, quarterly statements, selected ownership disclosures, corporate events, and trade context stay on separate tabs with source fields.</p></article><article class="card card-pad"><h3>Coverage limits</h3><p>Some issuers or periods are missing from particular reports. Change metrics only use issuers present in the required consecutive monthly reports. Trade data is sector context, not a company revenue proxy.</p></article></section>'}
function paperBooksPage(){const book='https://docs.google.com/spreadsheets/d/1hsT4CVPgtXMK8RLl24mZpPSbyp001eJJAa2UKzh89Y0/edit';const ideas=`${book}#gid=812190906`,dashboard=`${book}#gid=1803010225`,materials='https://drive.google.com/drive/folders/1_iITpp5f4tBL7HgifF1m8hxVFlgX230p',params=new URLSearchParams(location.hash.split('?')[1]||''),seed=params.get('idea')||'';return `${header('Private workspace','Paper books','Keep thesis edits, trades, exits, and monthly marks in a private Google Sheet.',`<span class="tag">Private Google account</span>`)}<section class="card card-pad section"><div class="card-head"><div><h2>Your paper-book files</h2><p class="sub">Holdings and thesis notes stay in the Sheet and Drive. This public page only links to them.</p></div></div><div class="card-actions"><a class="btn primary" href="${ideas}" target="_blank" rel="noreferrer">Open Ideas ↗</a><a class="btn" href="${dashboard}" target="_blank" rel="noreferrer">Open performance ↗</a><a class="btn" href="${materials}" target="_blank" rel="noreferrer">Upload materials ↗</a><a class="btn" href="#industries">Browse industry sources ↗</a></div><p class="footnote">After the one-time Apps Script setup, choose Paper Book, Add an idea inside the spreadsheet for a guided form. Until then, enter the same fields on the Ideas tab.</p></section><div class="industry-cards section"><article class="card card-pad"><h2>Start an idea</h2><p>Enter company, ticker, exchange, book, long or short, target size as % of NAV, conviction from 1 to 5, and a short thesis. Add the operating signal, metric-to-financial bridge, and evidence that would change your mind.</p><p class="footnote">With the helper installed, submission creates an Idea ID, a valuation row, and a private materials subfolder.</p></article><article class="card card-pad"><h2>Update or exit</h2><p>Edit the thesis and target size whenever your view changes. Record each fill in Transactions. To close an idea, set status to Exited, enter the date, and record the closing fill. Keep the original row and trades.</p></article><article class="card card-pad"><h2>Company valuation</h2><p>For supported SEC filers, the helper can fill reported shares, income, cash, debt, EBITDA, sales, and equity. Add a dated USD price and source yourself. The Sheet calculates market cap and supported multiples only from USD inputs. Review source periods, share class, and denominators.</p><p class="footnote">The helper is in this repository, not installed in the live Sheet yet. No free price feed has been verified for professional use.</p></article><article class="card card-pad"><h2>Performance</h2><p>Add one Monthly Marks row per book and month with beginning and ending NAV, benchmark levels, external flows, and flow timing. The dashboard calculates monthly and calendar-year returns, flow-adjusted drawdown, Sharpe, and information ratio.</p><p class="footnote">Sharpe and information ratio need 24 monthly returns. Trades do not create NAV or position-level returns automatically.</p></article></div><section class="card card-pad section"><div class="card-head"><div><h2>Find sources linked to an idea</h2><p class="sub">Search by industry, niche, metric, supplier, or question. A ticker by itself rarely identifies a free company-specific dataset.</p></div></div><form id="paper-source-form" class="project-form"><label class="field project-note"><span>Company, ticker, industry, niche, or operating question</span><input id="paper-source-query" type="search" maxlength="300" value="${esc(seed)}" placeholder="Example: TSMC advanced packaging capacity utilization"></label><button class="btn primary" type="submit">Find candidate sources</button></form><p class="footnote">Search stays in this browser. It does not save or send your terms. Results are discovery leads, not issuer coverage. Verify the source and copy useful links into Related research links in the private Sheet.</p><div id="paper-source-results" aria-live="polite"></div></section><section class="card card-pad section"><h2>Access and price limits</h2><p>Google account permissions protect the workbook. This is not a separate password set on the website. Check Drive sharing before adding sensitive material. Price stays manual because I could not verify a free quote source cleared for professional use. Non-USD prices are not supported in the current valuation template. SEC facts are reported fundamentals, not market data, and can be incomplete for foreign issuers and custom accounting tags.</p></section>`}
function renderPaperSources(query){const matches=sourcesForQuestion(query);const box=document.querySelector('#paper-source-results');if(!box)return;box.innerHTML=matches.length?`<h3>${matches.length} possible source links</h3><div class="industry-cards">${matches.map(s=>`<article class="card card-pad"><div class="card-head"><div><span class="tag">${esc(s.matchSector||'Source match')}</span><h3>${esc(s.title)}</h3></div><a class="btn" href="${esc(s.url)}" target="_blank" rel="noreferrer">Open source ↗</a></div><p>${esc(s.whatItMeasures||s.operatingMetricBridge?.hypothesis||'Review the provider page for current coverage.')}</p><p class="footnote">Matched on: ${esc(s.matchReason||'sector and operating terms')} · ${esc(s.freshness||s.evidenceReviewed||'Check the latest observation on the provider page.')}</p><p class="footnote">This is a discovery lead, not proof of coverage for the issuer. Check the source's geography, cadence, and definition before adding the link to the private idea.</p></article>`).join('')}</div>`:`<p class="empty">No source matched those terms. Add an industry niche, operating metric, supplier, or question. A ticker or company name alone may not map to an open company-specific dataset. Browse the full source library.</p>`}
function loadTaiwanFeed(){const url=window.FIELD_SIGNAL_TAIWAN_FEED_URL||'';if(!url)return;const status=document.querySelector('#taiwan-feed-status');fetch(url,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(`Google Sheets returned ${r.status}`);return r.text()}).then(text=>{const parsed=parseDelimited(text.replace(/^\uFEFF/,''),',');const i=parsed.findIndex(row=>row.some(v=>String(v).trim()==='Company code'));if(i<0)throw new Error('The published CSV has no SiteFeed header.');const headers=parsed[i].map(x=>String(x).trim());taiwanFeedRows=parsed.slice(i+1).filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(headers.map((h,j)=>[h,r[j]||''])));const latest=taiwanFeedRows.map(r=>taiwanMonthLabel(r['Report month'])).filter(Boolean).sort().at(-1)||'';status.className='footnote';status.textContent=`Loaded ${taiwanFeedRows.length.toLocaleString()} issuers. Latest report month: ${latest||'not available'}. History requires one row per consecutive report month.`;const count=document.querySelector('.hero-side strong');if(count)count.textContent=`${taiwanFeedRows.length.toLocaleString()} issuers`;renderTaiwanRows('')}).catch(err=>{status.className='callout';status.textContent=`Could not load the published Sheet feed: ${err.message}. Check that the SiteFeed tab is published as CSV and that the link is current.`;const count=document.querySelector('.hero-side strong');if(count)count.textContent='Feed unavailable'})}
function taiwanMonthLabel(value){const text=String(value||'').trim();let m=text.match(/^(\d{4})-(\d{2})/);if(m)return `${m[1]}-${m[2]}`;const serial=Number(text);if(Number.isFinite(serial)&&serial>20000&&serial<100000){const d=new Date(Math.round((serial-25569)*86400000));return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`}const d=new Date(text);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function taiwanMetric(value){const text=String(value??'').trim();if(!text)return 'Not reported';const n=Number(text.replace(/,/g,''));return Number.isFinite(n)?new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n):text}
function taiwanPercent(value){const text=String(value??'').trim();return text?taiwanMetric(text)+'%':'Not reported'}
function taiwanAccelerationValue(row){const numeric=value=>{const text=String(value??'').replace(/,/g,'').trim();if(!text)return NaN;const number=Number(text);return Number.isFinite(number)?number:NaN};const hasQuality=Object.prototype.hasOwnProperty.call(row,'Revenue denominator quality');if(hasQuality){if(row['Revenue denominator quality']!=='Usable'||row['Revenue growth outlier status']!=='None'||!String(row['Freshness status']||'').startsWith('Current'))return null}else{const current=numeric(row.Revenue),base=numeric(row['Revenue year-ago month']),yoy=numeric(row['Revenue YoY %']);if(!(current>0&&base>0)||base/current<.01||!Number.isFinite(yoy)||Math.abs(yoy)>=500)return null}const number=numeric(row['Revenue YoY Δ1 (pp/month)']);return Number.isFinite(number)?number:null}
function compareTaiwanAcceleration(a,b){const av=taiwanAccelerationValue(a),bv=taiwanAccelerationValue(b);if(av===null)return bv===null?0:1;if(bv===null)return -1;return bv-av}
function renderTaiwanRows(query){const target=document.querySelector('#taiwan-feed-table');if(!target)return;const q=String(query||'').trim().toLowerCase();const rows=taiwanFeedRows.filter(r=>!q||[r.Market,r['Company code'],r['Company name'],r['English company name or official abbreviation'],r.Industry].join(' ').toLowerCase().includes(q)).sort(compareTaiwanAcceleration);const pageSize=100;const pageCount=Math.max(1,Math.ceil(rows.length/pageSize));taiwanPageNumber=Math.min(taiwanPageNumber,pageCount-1);const visible=rows.slice(taiwanPageNumber*pageSize,(taiwanPageNumber+1)*pageSize);if(!visible.length){target.innerHTML='<p class="empty">No matching issuers.</p>';return}const body=visible.map(r=>{const code=esc(r['Company code']||'');const chinese=esc(r['Company name']||'');const english=esc(r['English company name or official abbreviation']||'');const pronunciationUrl=r['Mandarin pronunciation lookup'];const lookup=pronunciationUrl?'<a href="'+esc(pronunciationUrl)+'" target="_blank" rel="noreferrer">Pronunciation ↗</a>':'';const source=r['Monthly source URL']?'<a href="'+esc(r['Monthly source URL'])+'" target="_blank" rel="noreferrer">Open source ↗</a>':'Source link unavailable';const details='<details class="tw-more"><summary>Trend and source</summary><dl><dt>Prior month revenue</dt><dd>'+esc(taiwanMetric(r['Revenue prior month']))+' TWD k</dd><dt>Same month last year</dt><dd>'+esc(taiwanMetric(r['Revenue year-ago month']))+' TWD k</dd><dt>Reported MoM growth</dt><dd>'+esc(taiwanPercent(r['Revenue MoM %']))+'</dd><dt>Monthly YoY growth</dt><dd>'+esc(taiwanPercent(r['Revenue YoY %']))+'</dd><dt>Change in YoY growth</dt><dd>'+esc(taiwanMetric(r['Revenue YoY Δ1 (pp/month)']))+' pp/month</dd><dt>Second difference</dt><dd>'+esc(taiwanMetric(r['Revenue YoY Δ2 (pp/month²)']))+' pp/month²</dd><dt>Third difference</dt><dd>'+esc(taiwanMetric(r['Revenue YoY Δ3 (pp/month³)']))+' pp/month³</dd><dt>YTD revenue</dt><dd>'+esc(taiwanMetric(r['Revenue YTD']))+' TWD k</dd><dt>Prior-year YTD revenue</dt><dd>'+esc(taiwanMetric(r['Revenue prior-year YTD']))+' TWD k</dd><dt>YTD growth</dt><dd>'+esc(taiwanPercent(r['Revenue YTD growth %']))+'</dd><dt>Consecutive reports</dt><dd>'+esc(r['Consecutive monthly observations']||'—')+'</dd><dt>Gross margin</dt><dd>'+esc(taiwanPercent(r['Gross margin %']))+'</dd><dt>Operating margin</dt><dd>'+esc(taiwanPercent(r['Operating margin %']))+'</dd><dt>Coverage note</dt><dd>'+esc(r['Data status']||'—')+'</dd></dl>'+lookup+' · '+source+'</details>';return '<tr><td class="tw-company"><strong>'+ (english||chinese) +'</strong><br><small>'+chinese+' · '+code+'</small></td><td>'+esc(r.Market||'—')+'</td><td>'+esc(r.Industry||'—')+'</td><td>'+esc(taiwanMonthLabel(r['Report month'])||r['Report month']||'—')+'</td><td>'+esc(taiwanMetric(r.Revenue))+'</td><td>'+esc(taiwanPercent(r['Revenue YoY %']))+'<br><small>base '+esc(taiwanMetric(r['Revenue year-ago month']))+' TWD k</small></td><td>'+details+'</td></tr>'}).join('');target.innerHTML='<table class="source-table"><thead><tr><th>Company</th><th>Market</th><th>Industry</th><th>Report month</th><th>Revenue · TWD k</th><th>YoY · prior-year base</th><th>More</th></tr></thead><tbody>'+body+'</tbody></table><div class="card-actions" style="justify-content:space-between;margin-top:10px"><button class="btn" data-tw-page="prev" '+(taiwanPageNumber===0?'disabled':'')+'>Previous</button><span class="footnote">Page '+(taiwanPageNumber+1)+' of '+pageCount+' · '+rows.length.toLocaleString()+' issuers</span><button class="btn" data-tw-page="next" '+(taiwanPageNumber>=pageCount-1?'disabled':'')+'>Next</button></div><p class="footnote">YoY is growth in monthly revenue. The prior-year monthly base is shown beside it because small bases can produce huge rates. Δ1 to Δ3 measure changes in reported YoY growth, not forecasts.</p>';target.querySelectorAll('[data-tw-page]').forEach(button=>button.addEventListener('click',()=>{taiwanPageNumber+=button.dataset.twPage==='next'?1:-1;renderTaiwanRows(query)}))}
function messyImporter(){const imp=read('import',{});return `  <section class="card card-pad section"><div class="card-head"><div><h2>Single-series CSV chart</h2><p class="sub">Map columns and chart a normalized time series. Source details stay beside the chart. Your file stays in this browser.</p></div><span class="tag gray">Local only</span></div><div class="import-meta"><div class="field"><label for="series-name">Series or source name</label><input id="series-name" placeholder="e.g. IBEW hourly scale by local" value="${esc(imp.sourceName||'')}"></div><div class="field"><label for="series-url">Source URL</label><input id="series-url" type="url" placeholder="https://..." value="${esc(imp.url||'')}"></div><div class="field"><label for="series-unit">Metric and unit</label><input id="series-unit" placeholder="e.g. calls, hourly dollars" value="${esc(imp.unit||'')}"></div><div class="field"><label for="series-geo">Geography or coverage</label><input id="series-geo" placeholder="e.g. US IBEW local 26" value="${esc(imp.geography||'')}"></div><div class="field"><label for="date-format">Date format</label><select id="date-format"><option value="auto">Recognized dates; reject ambiguity</option><option value="us">Month / day / year</option><option value="dayfirst">Day / month / year</option><option value="excel">Excel date serial</option></select></div><div class="field"><label for="number-format">Number format</label><select id="number-format"><option value="auto">Detect automatically</option><option value="us">1,234.56</option><option value="eu">1.234,56</option></select></div></div><div class="import-box"><label for="csv-file">Choose CSV or TSV</label><input type="file" id="csv-file" accept=".csv,.tsv,text/csv,text/tab-separated-values"><span id="import-status">Choose a delimited file. You can map its columns before importing. The file is not uploaded.</span></div><div id="import-preview">${renderImport()}</div><p class="footnote">Supports title or note rows above a selectable header row, then expects one observation per row. Auto mode accepts ISO and unambiguous dates; choose US or day-first for ambiguous values and Excel mode for serial dates. Monthly periods stay labeled YYYY-MM. A percent sign is removed while keeping the number as percentage points, so 12% becomes 12; label the unit as % when appropriate. It does not reshape wide tables or remove duplicate rows. Downloaded CSV contains only normalized saved rows. Check the data-quality counts and keep the source file and its definitions.</p></section>`}
function importerPage(){return `${header('Data staging inbox','Inspect raw data before you use it.','Map columns, keep the source and period, and log corrections. Nothing is uploaded.',`<strong>Local only</strong>`)}<section class="section" data-inbox-panel>${window.FieldSignalsModules.messyDataInbox.render()}</section>${messyImporter()}<p class="footnote"><a href="#industries">Browse 220 open tools</a> · <a href="#lab">Capacity and thesis tools</a></p>`}
function sourceRow(s){return `<article class="card source-row"><div><h3>${esc(s.name)}</h3><span class="tag">${esc(s.type)}</span></div><div><p><strong>${esc(s.observed)}</strong> · ${esc(s.geography)}</p><p>${esc(s.note)}</p></div><a class="btn" href="${s.url}" target="_blank" rel="noreferrer">Open source ↗</a></article>`}
function capacitySources(){const baseNames=['US Data Center Map','Berkeley Lab interconnection queues','BLS electrician wages by metro','Census construction spending'];const base=baseNames.map(name=>sources.find(x=>x.name===name)).filter(Boolean).map(s=>({name:s.name,url:s.url,frequency:s.frequency,observed:s.observed,note:s.note}));const wanted=['eia-hourly-grid-monitor','eia-860m-generator-inventory','nerc-long-term-reliability-assessment'];const added=(window.industryModules?.sectors||[]).flatMap(g=>g.cards).filter(c=>wanted.includes(c.id)).map(c=>({name:c.title,url:c.url,frequency:c.freshness.split('.')[0],observed:c.evidenceReviewed,note:c.whatItMeasures}));return `<section class="section"><div class="section-title"><div><h2>Source map</h2><p>Each source covers one stage. No single public dataset links a named project to labor, grid supply, and company revenue.</p></div><a href="#sources">Freshness register ↗</a></div><div class="capacity-map" aria-label="Evidence stages from project pipeline to company results"><article class="capacity-map-stage"><span class="tag">1 · Project pipeline</span><h3>Announced build</h3><p>Facility maps, stated MW, milestones, funding, and planned timing.</p><a href="https://dcmap.us/about/" target="_blank" rel="noreferrer">US Data Center Map ↗</a><a href="https://www.nist.gov/chips/funding-updates" target="_blank" rel="noreferrer">CHIPS award updates ↗</a></article><b class="capacity-map-arrow" aria-hidden="true">→</b><article class="capacity-map-stage"><span class="tag">2 · Build constraints</span><h3>Labor and construction</h3><p>Local union calls and wage scales, plus aggregate construction spending.</p><a href="https://goherebro.com/map" target="_blank" rel="noreferrer">GoHereBro IBEW calls ↗</a><a href="https://www.bls.gov/oes/CURRENT/oessrcma.htm" target="_blank" rel="noreferrer">BLS electrician wages ↗</a></article><b class="capacity-map-arrow" aria-hidden="true">→</b><article class="capacity-map-stage"><span class="tag">3 · Grid and supply</span><h3>Connection and power</h3><p>Queue requests, planned generation, hourly demand, and reliability forecasts.</p><a href="https://emp.lbl.gov/queues" target="_blank" rel="noreferrer">Berkeley Lab queues ↗</a><a href="https://www.eia.gov/electricity/data/eia860m/" target="_blank" rel="noreferrer">EIA generator inventory ↗</a><a href="https://www.eia.gov/electricity/gridmonitor/" target="_blank" rel="noreferrer">EIA hourly grid monitor ↗</a></article><b class="capacity-map-arrow" aria-hidden="true">→</b><article class="capacity-map-stage"><span class="tag">4 · Operating result</span><h3>Energized capacity and economics</h3><p>Verify project energization, utilization, lease-up, power cost, and capex in company and utility filings.</p><a href="#tracker">Record the evidence in your notebook ↗</a></article></div><p class="callout">The arrows are a diligence sequence, not a demonstrated causal chain. Public project, labor, and grid data do not identify the same facilities or prove when customer power is available.</p><div class="capacity-sources">${[...base,...added].map(s=>`<a class="card source-mini" href="${esc(s.url)}" target="_blank" rel="noreferrer"><span class="tag">${esc(s.frequency)}</span><h3>${esc(s.name)}</h3><p>${esc(s.observed)}</p><small>${esc(s.note)}</small><b>Open source ↗</b></a>`).join('')}</div><p class="footnote">US Energy Map's free map view remains available, but its downloadable data feed is paid. dcmap.us is an overlapping free map alternative. This page does not combine or geocode the providers' records.</p></section>`}
function capacity(){
  const s=sources.find(x=>x.name.startsWith('GoHereBro'));
  return `${header('Capacity signals','Track labor, grid, and project evidence around major builds.','A practical starting signal for data-center, semiconductor-fab, and industrial construction. The source maps union halls, not project sites.',`<strong>US</strong> IBEW inside locals`)}
  <div class="capacity-layout">
    <section class="card card-pad"><div class="card-head"><div><span class="tag green">Free account for map details</span><h2 style="margin-top:8px">GoHereBro IBEW Job Call Map</h2><p class="sub">Open calls, local journeyman scale, and book counts by IBEW local.</p></div><a class="btn primary" href="${s.url}" target="_blank" rel="noreferrer">Open live map ↗</a></div>
      <div class="capacity-facts"><div><small>Page date when checked</small><strong>11 Oct 2026</strong></div><div><small>Coverage stated by provider</small><strong>About 300 local unions</strong></div><div><small>Pay scale source</small><strong>Where2Bro, refreshed daily per help page</strong></div></div>
      <p>${esc(s.note)}</p><p class="sub">GoHereBro says core job-call, scale, and book data are free with an account. Its guide separately advertises paid founder features such as alerts. This directory links to the provider and does not copy its live feed.</p>
    </section>
    <section class="card card-pad"><h2>How to use it in a capacity question</h2><ol class="capacity-steps"><li>Start with a named project or build corridor and its expected construction period.</li><li>Check nearby locals for persistent open calls, book movement, call descriptions, and scale changes.</li><li>Match those observations to project schedules and contractor evidence before calling it a bottleneck.</li></ol><div class="callout">A high count of open calls is not a count of data-center vacancies. Calls are listed by union hall, and the actual project may be elsewhere in that hall's territory. Some projects use nonunion labor or do not post identifiable site details.</div></section>
  </div>
  <section class="card card-pad section"><div class="card-head"><div><h2>Possible operating-metric bridge</h2><p class="sub">A hypothesis to test, not an earnings conversion.</p></div><span class="tag amber">Needs project-level evidence</span></div><div class="bridge-flow"><div><small>Observed signal</small><strong>Open calls and union scale by local</strong></div><b>→</b><div><small>Possible mechanism</small><strong>Availability and cost of skilled electricians</strong></div><b>→</b><div><small>Company KPI</small><strong>Construction progress or capacity energization dates</strong></div><b>→</b><div><small>Financial line</small><strong>Capex timing, depreciation, and revenue from installed capacity</strong></div></div><p class="footnote">Each arrow needs evidence. Hall-level calls can reflect projects unrelated to data centers, so tie any read to named contractors, sites, schedules, and company reporting.</p></section>
  ${capacityProjectRegister()}
  ${capacitySources()}
  <section class="section"><div class="section-title"><div><h2>What would make the signal stronger?</h2><p>Use source receipts and record what would change your read.</p></div><a href="#tracker">Open research notebook ↗</a></div><div class="capacity-checks"><article class="card card-pad"><span class="tag">Potential constraint</span><p>Calls stay elevated near named data-center or fab projects, and job descriptions identify the same contractor or build corridor.</p></article><article class="card card-pad"><span class="tag gray">Alternative read</span><p>Open calls reflect unrelated construction, seasonal timing, dispatch rules, or multiple positions attached to one project.</p></article><article class="card card-pad"><span class="tag amber">Cross-check</span><p>Look for project schedules, permits, contractor announcements, utility work, and company disclosures before connecting labor data to capacity.</p></article></div></section>
  <section class="card card-pad section"><div class="card-head"><div><h2>Source freshness receipt</h2><p class="sub">The map page says calls refresh through the day. Its getting-started guide says every 30 minutes. Check the displayed update before relying on a call.</p></div><span class="tag amber">Refresh cadence varies by page</span></div><div class="receipt"><div><small>Last checked</small><strong>${esc(s.checked)}</strong></div><div><small>Latest page date</small><strong>${esc(s.observed)}</strong></div><div><small>Access</small><strong>${esc(s.access)}</strong></div><div><small>Data limitation</small><strong>Union hall counts, not project-site staffing</strong></div></div><p class="footnote">${esc(s.license)}</p></section>`
}
function renderReceipts(){const items=read('receipts',[]);if(!items.length)return '<p class="empty-receipts">No receipts saved yet. Add a dated observation, interpretation, and source link above.</p>';return `<div class="receipt-stack">${items.slice(0,20).map(x=>`<article class="receipt-item"><div class="receipt-item-head"><strong>${esc(x.question||'Research observation')}</strong><span class="tag gray">Observed ${esc(x.observedDate)}</span></div><p><strong>Observation:</strong> ${esc(x.observation||'Not recorded')}</p><p><strong>Interpretation:</strong> ${esc(x.interpretation||'Not recorded')}</p><p><strong>Could weaken it:</strong> ${esc(x.falsifier||'Not recorded')}</p><div class="receipt-meta"><span><strong>Source date:</strong> ${esc(x.sourceDate||'Not recorded')}</span><span><strong>Geography:</strong> ${esc(x.geography||'Not recorded')}</span><span><strong>Measure:</strong> ${esc(x.definition||'Not recorded')}</span><span><strong>Revision:</strong> ${esc(x.revision||'Not recorded')}</span></div>${x.bridgeSignal||x.bridgeMechanism||x.bridgeKpi||x.bridgeFinancial?`<div class="saved-bridge"><strong>Operating-metric bridge</strong><p>${[x.bridgeSignal,x.bridgeMechanism,x.bridgeKpi,x.bridgeFinancial].filter(Boolean).map(esc).join(' → ')}</p><small>Alternative explanation: ${esc(x.bridgeBreak||'Not recorded')}</small></div>`:''}<a href="${esc(x.url)}" target="_blank" rel="noreferrer">${esc(x.url)}</a><small>Saved ${esc(x.savedAt)}</small></article>`).join('')}</div>`}
function sourcesPage(){const sectorCards=(window.industryModules?.sectors||[]).flatMap(g=>g.cards.map(c=>({sector:g.name,name:c.title,url:c.url,frequency:'',observed:c.freshness,checked:window.industryModules.reviewedAt,access:c.accessAndReuse,note:c.whatItMeasures,license:c.accessAndReuse,reviewed:c.evidenceReviewed})));const byUrl=new Map(sources.map(s=>[s.url,s]));for(const s of sectorCards)if(!byUrl.has(s.url))byUrl.set(s.url,s);const all=[...byUrl.values()];return `${header('Source freshness register','When was the data updated?','Compare the latest observation with the date the source was reviewed. Check access, reuse, and measurement limits before using a signal.',`<strong>${all.length}</strong> source pages`)}<section class="source-list">${all.map(s=>`<article class="card card-pad"><div class="card-head"><div>${s.sector?`<span class="tag">${esc(s.sector)}</span> `:''}${s.frequency?`<span class="tag ${s.frequency==='Monthly'?'green':''}">${esc(s.frequency)}</span> `:''}<span class="tag gray">${esc(s.type||'Public source')}</span><h2 style="margin-top:8px">${esc(s.name)}</h2><p class="sub">${esc(s.geography||'See provider coverage')}</p></div><div class="card-actions"><a class="btn" href="${esc(s.url)}" target="_blank" rel="noreferrer">Visit source ↗</a>${trackButton({title:s.name,url:s.url,measure:s.type||'Public signal',sector:s.sector||''})}</div></div><div class="receipt"><div><small>${s.sector?'Provider freshness note':'Latest observation or release'}</small><strong>${esc(s.observed)}</strong></div><div><small>Page checked</small><strong>${esc(s.checked||window.industryModules?.reviewedAt)}</strong></div><div><small>${s.sector?'Access and reuse':'Free access'}</small><strong>${esc(s.access)}</strong></div><div><small>${s.sector?'Evidence checked':'Reuse note'}</small><strong>${esc(s.sector?s.reviewed:s.license)}</strong></div></div><p class="sub" style="margin-top:10px">${esc(s.note)}</p></article>`).join('')}</section><p class="footnote">Research pages were reviewed 12 October 2026. An advertised cadence does not confirm a current observation. Recheck provider pages before using the data.</p>`}
function sourcesForQuestion(text){
  const sectors=window.industryModules?.sectors||[],tokens=[...new Set(String(text||'').toLowerCase().match(/[a-z0-9]+/g)||[])].filter(t=>t.length>2&&!['the','and','for','with','from','how','what','company','ticker','data','source','track','about'].includes(t));
  if(!tokens.length)return [];
  const q=String(text||'').toLowerCase(),preferred=[];
  const route=(pattern,ids)=>{if(pattern.test(q))preferred.push(...ids)};
  route(/data.?center|capacity|electric|construction|grid|labor|labour|fab|facility/,['goherebro-ibew-calls','nist-chips-funding-updates','eia-hourly-grid-monitor','eia-860m-generator-inventory','nerc-long-term-reliability-assessment']);
  route(/compute|gpu|cloud|server|accelerator|inference|training/,['computepulse-gpu-prices']);
  route(/semiconductor|chip|memory|foundry|wafer|equipment|fab/,['fed-semiconductor-industrial-production','sia-wsts-monthly-sales','tsmc-monthly-revenue','nist-chips-funding-updates']);
  route(/media|stream|music|subscriber|engagement|gaming|game|artist|label|viewing|netflix|spotify/,['nielsen-the-gauge','netflix-top10','spotify-charts','steamdb-player-charts']);
  route(/consumer|retail|search|brand|demand|store|shopping/,['census-monthly-retail-trade','google-trends-consumer-interest']);
  route(/natural gas|gas storage|pipeline|lng|energy|oil|petroleum|gasoline|refining/,['eia-weekly-natural-gas-storage','eia-weekly-petroleum-status']);
  route(/material|mineral|metal|copper|gold|lithium|steel/,['usgs-mineral-statistics']);
  route(/airline|flight|aviation|airport|durable|manufactur|orders|backlog/,['bts-airline-on-time-performance','census-m3-orders-inventories']);
  route(/port|shipping|container|freight|logistics/,['port-la-container-statistics']);
  route(/pce|personal consumption|consumer spending|household spending/,['bea-personal-consumption-expenditures']);
  route(/grocery|food|egg|staple|supermarket/,['usda-egg-feature-activity']);
  route(/health|clinical|trial|pharma|drug|medicine|prescription|medicare/,['cms-quarterly-partd-spending','clinicaltrials-gov-registry']);
  route(/bank|financial|deposit|credit|lender|loan/,['federal-reserve-h8-bank-assets-liabilities','fdic-bankfind-financial-reports']);
  route(/utility|power plant|generation|electricity supply|electric grid/,['eia-hourly-grid-monitor','eia-860m-generator-inventory','eia-923-plant-operations']);
  route(/real estate|housing|home price|rent|apartment/,['zillow-research-housing-data']);
  route(/broadband|fiber|wireless|telecom|internet coverage/,['fcc-national-broadband-map']);
  const items=[];
  sectors.forEach(group=>group.cards.forEach(card=>items.push({...card,matchSector:group.name,searchText:[group.name,card.title,card.provider,card.whatItMeasures,card.accessAndReuse,card.freshness,card.operatingMetricBridge?.metric,card.operatingMetricBridge?.hypothesis,card.operatingMetricBridge?.limits].join(' ').toLowerCase()})));
  sources.forEach(item=>items.push({id:'source-'+item.name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),title:item.name,url:item.url,whatItMeasures:item.note,accessAndReuse:item.access,operatingMetricBridge:{metric:item.type},freshness:`${item.frequency}. Latest checked observation: ${item.observed}.`,matchSector:'Cross-industry source',searchText:[item.name,item.type,item.geography,item.frequency,item.note].join(' ').toLowerCase()}));
  const preferredSet=new Set(preferred),ranked=items.map(item=>{
    const fields=[item.title||'',item.provider||'',item.matchSector||'',item.operatingMetricBridge?.metric||'',item.whatItMeasures||'',item.operatingMetricBridge?.hypothesis||'',item.operatingMetricBridge?.limits||'',item.searchText||''].join(' ').toLowerCase();
    const wordMatch=(field,token)=>new RegExp('(^|[^a-z0-9])'+token+'([^a-z0-9]|$)').test(field);
    const hits=tokens.filter(token=>wordMatch(fields,token));
    const direct=preferredSet.has(item.id);
    const titleHits=tokens.filter(token=>wordMatch(String(item.title||'').toLowerCase(),token));
    const score=(direct?20:0)+(titleHits.length*5)+(hits.length*2);
    if(!score)return null;
    const matchReason=direct?'matches the operating topic':`matches ${[...new Set([...titleHits,...hits])].slice(0,4).join(', ')}`;
    return {...item,score,matchReason};
  }).filter(Boolean).sort((a,b)=>b.score-a.score||String(a.title).localeCompare(String(b.title)));
  const unique=new Set();
  return ranked.filter(item=>{if(!safeUrl(item.url)||unique.has(item.url))return false;unique.add(item.url);return true}).slice(0,6);
}
function makePlan(fd){const company=fd.get('company')||'the company or value chain',q=fd.get('question')||'the operating question',geo=fd.get('geography')||'Not specified',matches=sourcesForQuestion(`${company} ${q}`);return `<h3>Research plan · ${esc(company)}</h3><p><strong>Question:</strong> ${esc(q)}</p><p><strong>Define the measure:</strong> choose the unit, geography, time window, and expected direction before collecting observations.</p><p><strong>Geography:</strong> ${esc(geo)}. Record where the signal is measured and whether it overlaps the company's actual operations.</p><p><strong>Open sources to start with:</strong></p>${matches.length?`<ul>${matches.map(c=>`<li><a href="${esc(c.url)}" target="_blank" rel="noreferrer">${esc(c.title)}</a>: ${esc(c.whatItMeasures)} <em>${esc(c.freshness)}</em></li>`).join('')}</ul>`:'<p>No sector-specific match found. Search the industry library by sector, company metric, or source name.</p>'}<p><strong>Cross-check:</strong> compare the series with an independent operational source and the company's reported data where available. Keep conflicting definitions separate.</p><p><strong>What would weaken the thesis?</strong> Write a specific observation that would contradict the expected direction, and a plausible alternative explanation for the signal.</p><button class="btn" id="copy-plan">Copy brief</button> <button class="btn primary" id="save-plan">Save question to notebook</button> <span class="footnote">Generated locally from this form. No external AI call was made.</span>`}
